func (this *LighterCore) ParsePosition(position any, optionalArgs ...any) any {
	//
	//     {
	//         "market_id": 0,
	//         "symbol": "ETH",
	//         "initial_margin_fraction": "5.00",
	//         "open_order_count": 0,
	//         "pending_order_count": 0,
	//         "position_tied_order_count": 0,
	//         "sign": 1,
	//         "position": "18.0193",
	//         "avg_entry_price": "2669.84",
	//         "position_value": "54306.566340",
	//         "unrealized_pnl": "6197.829558",
	//         "realized_pnl": "0.000000",
	//         "liquidation_price": "2191.1107231380406",
	//         "margin_mode": 0,
	//         "allocated_margin": "0.000000"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "market_id")
	market = this.SafeMarket(marketId, market)
	var sign *int64 = this.SafeInteger(position, "sign")
	var side any = nil
	if sign != nil {
		side = Ternary((sign != nil && *sign == 1), "long", "short")
	}
	var marginModeId *int64 = this.SafeInteger(position, "margin_mode")
	var marginMode any = nil
	if marginModeId != nil {
		marginMode = Ternary((marginModeId != nil && *marginModeId == 0), "cross", "isolated")
	}
	var imfStr *string = this.SafeString(position, "initial_margin_fraction")
	var leverage any = nil
	if imfStr != nil {
		var imf any = this.ParseToInt(imfStr)
		if IsGreaterThan(imf, 0) {
			leverage = Divide(100, imf)
		}
	}
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      GetValue(market, "symbol"),
		"timestamp":                   nil,
		"datetime":                    nil,
		"isolated":                    (IsEqual(marginMode, "isolated")),
		"hedged":                      nil,
		"side":                        side,
		"contracts":                   this.SafeNumber(position, "position"),
		"contractSize":                nil,
		"entryPrice":                  this.SafeNumber(position, "avg_entry_price"),
		"markPrice":                   nil,
		"notional":                    this.SafeNumber(position, "position_value"),
		"leverage":                    leverage,
		"collateral":                  this.SafeNumber(position, "allocated_margin"),
		"initialMargin":               nil,
		"maintenanceMargin":           nil,
		"initialMarginPercentage":     nil,
		"maintenanceMarginPercentage": nil,
		"unrealizedPnl":               this.SafeNumber(position, "unrealized_pnl"),
		"liquidationPrice":            this.SafeNumber(position, "liquidation_price"),
		"marginMode":                  marginMode,
		"percentage":                  nil,
	})
}

